import os, json, re

dirs = [
    '/Users/dev/.gemini/antigravity/brain',
    '/Users/dev/.gemini/antigravity-cli/brain'
]

keywords = ['trading', 'bot', 'crypto', 'binance', 'bybit', 'forex', 'stocks', 'algorithmic', 'paper trade']

results = {}

for base in dirs:
    if not os.path.exists(base): continue
    for cid in os.listdir(base):
        p = os.path.join(base, cid, '.system_generated', 'logs', 'transcript.jsonl')
        if not os.path.exists(p): continue
        mtime = os.path.getmtime(p)
        matched_kw = set()
        user_msgs = []
        with open(p, 'r', errors='ignore') as f:
            for line in f:
                try:
                    d = json.loads(line)
                    t = d.get('type')
                    c = d.get('content', '')
                    if t == 'USER_INPUT':
                        user_msgs.append(c)
                    c_low = c.lower()
                    for kw in keywords:
                        if kw in c_low:
                            matched_kw.add(kw)
                except:
                    pass
        if 'trading' in matched_kw or ('bot' in matched_kw and 'crypto' in matched_kw):
            results[cid] = (mtime, base, matched_kw, user_msgs)

items = sorted(results.items(), key=lambda x: x[1][0], reverse=True)
for cid, (mtime, base, matched_kw, msgs) in items:
    print('='*50)
    print(f'CID: {cid} | Dir: {os.path.basename(os.path.dirname(base))} | Keywords: {matched_kw}')
    for m in msgs[:3]:
        # clean m
        clean_m = re.sub(r'<.*?>', '', m).strip()
        print('  User:', clean_m.replace('\n', ' ')[:120])
